create or replace function public.current_user_plan(p_user_id uuid default auth.uid()) returns table(plan_id uuid,plan_code text,plan_name text,status text,billing_interval text,limits jsonb) language sql stable security invoker set search_path=public as $$ with active as (select p.id,p.code,p.name,s.status,s.billing_interval,p.limits,s.created_at from public.subscriptions s join public.plans p on p.id=s.plan_id where s.user_id=p_user_id and s.status in ('trialing','active','past_due','paused') order by s.created_at desc limit 1) select id,code,name,status,billing_interval,limits from active union all select p.id,p.code,p.name,'active','free',p.limits from public.plans p where p.code='free' and p.is_active=true and not exists(select 1 from active) limit 1; $$; create or replace function public.user_has_plan_feature(p_feature_key text,p_user_id uuid default auth.uid()) returns boolean language sql stable security invoker set search_path=public as $$ select exists(select 1 from public.current_user_plan(p_user_id) c join public.plan_features pf on pf.plan_id=c.plan_id where pf.feature_key=p_feature_key and pf.enabled=true); $$;
